-- Round 4: polls ("Planlæg ølsmagning"; SPEC §9.7, §11; D-129–D-139) and
-- TG-032 (events.location_text is dropped).
--
-- Generated by `prisma migrate dev --create-only` (here: `prisma migrate diff`,
-- because migrate dev refuses the column drop non-interactively), then edited
-- by hand in exactly two places (keep it that way, or the next `migrate dev`
-- proposes a reset, F-009):
--   (a) events_location_text_length_check is dropped explicitly before the
--       column (Postgres would drop it with the column; the line documents it).
--   (b) the CHECK constraints are appended at the end.
-- Prisma sends the script as one implicit transaction, so any failure rolls
-- everything back.

-- CreateEnum
CREATE TYPE "poll_status" AS ENUM ('OPEN', 'AWAITING_DECISION', 'CLOSED', 'CANCELLED');

