-- CreateEnum
CREATE TYPE "poll_category" AS ENUM ('DATE', 'PLACE');

-- Hand edit (a): the round-2 CHECK goes explicitly, before its column (TG-032).
ALTER TABLE "events" DROP CONSTRAINT IF EXISTS "events_location_text_length_check";

-- AlterTable
ALTER TABLE "events" DROP COLUMN "location_text",
ADD COLUMN     "poll_id" TEXT;

