-- ─── Hand edit (b): CHECK constraints (SPEC §11, D-129) ─────────────────────
-- Prisma cannot express CHECKs and ignores them when diffing (F-004: CHECKs
-- only, never raw indexes or FKs). The app validates first
-- (src/lib/validation/poll.ts, src/server/domain/polls/*); these guard every
-- writer. title/theme/description are the SAME as events', so copying them
-- into the poll's event can never fail (§9.7.7). There is deliberately no
-- "deadline > created_at": tests and E2E helpers move deadlines into the past.

ALTER TABLE "polls" ADD CONSTRAINT "polls_title_length_check"
  CHECK (char_length(btrim("title")) BETWEEN 1 AND 100);

ALTER TABLE "polls" ADD CONSTRAINT "polls_theme_length_check"
  CHECK ("theme" IS NULL OR char_length(btrim("theme")) BETWEEN 1 AND 80);

ALTER TABLE "polls" ADD CONSTRAINT "polls_description_length_check"
  CHECK ("description" IS NULL OR char_length(btrim("description")) BETWEEN 1 AND 5000);

-- OPEN: nothing about the end is set.
ALTER TABLE "polls" ADD CONSTRAINT "polls_lifecycle_open_check" CHECK (
  "status" <> 'OPEN' OR ("close_reason" IS NULL AND "closed_at" IS NULL AND "closed_by_id" IS NULL
                         AND "cancelled_at" IS NULL AND "cancelled_by_id" IS NULL));

-- AWAITING_DECISION / CLOSED: voting ended, not cancelled.
ALTER TABLE "polls" ADD CONSTRAINT "polls_lifecycle_decided_check" CHECK (
  "status" NOT IN ('AWAITING_DECISION', 'CLOSED')
  OR ("close_reason" IS NOT NULL AND "cancelled_at" IS NULL AND "cancelled_by_id" IS NULL));

-- CANCELLED: who and when (close_* stay set if it was AWAITING_DECISION).
ALTER TABLE "polls" ADD CONSTRAINT "polls_lifecycle_cancelled_check" CHECK (
  "status" <> 'CANCELLED' OR ("cancelled_at" IS NOT NULL AND "cancelled_by_id" IS NOT NULL));

ALTER TABLE "polls" ADD CONSTRAINT "polls_close_pair_check"
  CHECK (("close_reason" IS NULL) = ("closed_at" IS NULL));

ALTER TABLE "polls" ADD CONSTRAINT "polls_manual_closer_check"
  CHECK (("close_reason" IS NOT DISTINCT FROM 'MANUAL') = ("closed_by_id" IS NOT NULL));

-- A date option has a time and no place; a place option a place and no time.
ALTER TABLE "poll_options" ADD CONSTRAINT "poll_options_category_check" CHECK (
  ("category" = 'DATE'  AND "starts_at" IS NOT NULL AND "place_id" IS NULL) OR
  ("category" = 'PLACE' AND "place_id"  IS NOT NULL AND "starts_at" IS NULL));
